export function normalizeCard(card,original=card){return original.oracle_text===TEXT[original.name]?{...card,oracle_text:original.oracle_text}:card;}

export function extensionEffect(card,text,h){
 if(text==="Choose up to two target creature cards in your graveyard. An opponent chooses one of them. Return that card to your hand. Return the other to the battlefield under your control. It gains haste. Exile it at the beginning of the next end step.")return {effects:[cohort('opponent-split-hand-battlefield',{target:0})],targets:[target('creature','you','graveyard',{min:0,max:2})],optional:false};
 if(text==='Target nonsnow permanent becomes snow until end of turn.')return {effects:[{action:'animate',target:0,types:[],subtypes:[],retainTypes:true,retainAllSubtypes:true,addSuperV20:['Snow'],temporary:true}],targets:[target('permanent','any','battlefield',{nonsnow:true})],optional:false};
 if(text==="Target snow permanent isn't snow until end of turn.")return {effects:[{action:'animate',target:0,types:[],subtypes:[],retainTypes:true,retainAllSubtypes:true,removeSuperV42:['Snow'],temporary:true}],targets:[target('permanent','any','battlefield',{snow:true})],optional:false};
 if(text==="Choose target artifact card in your graveyard. Return it to the battlefield if it's an artifact creature card. Otherwise, return it to the battlefield and it's a 3/3 Robot artifact creature with flying.")return {effects:[cohort('robot-artifact-return',{target:0})],targets:[target('artifact','you','graveyard')],optional:false};

 if(text==='Tap up to three target creatures. Put a stun counter on one of them.')return {effects:[{action:'tap',target:0},cohort('selected-stun',{target:0,n:1})],targets:[creature('any',{min:0,max:3})],optional:false};
 if(text==='Exile all artifacts, creatures, and lands from the battlefield, all cards from all graveyards, and all cards from all hands.')return {effects:[cohort('annihilate-zones')],targets:[],optional:false};

 if(text==='Exile up to twice X target cards from graveyards.')return {effects:[{action:'exile',target:0}],targets:[{what:'card',zone:'graveyard',controller:'any',min:0,max:0,targetCountX:true,upToXV38:true,targetCountMultiplierV57:2}],optional:false};
 if(text==='Draw cards equal to the greatest power among creatures you control. You lose life equal to the number of cards drawn this way.')return {effects:[cohort('max-power-draw-lose')],targets:[],optional:false};
 if(text==='Counter target spell unless its controller pays twice {X}.')return {effects:[{action:'counter-spell',target:0,unlessGeneric:{kind:'sum',values:['X','X']}}],targets:[target('spell','any','stack')],optional:false};
 return null;
}
